-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 2
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 02 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 02', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 02 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-02.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Cite as três formas geométricas básicas do design digital.', 0.2, 'As três formas geométricas básicas do design digital são o retângulo, o círculo e o triângulo.', 'Nota cheia: cita as três formas (retângulo, círculo e triângulo). Metade: cita duas das três formas. Zero: cita outra forma, cita imagens ou fica em branco.'),
      (v_atividade, 1, 2, 'Relacione cada forma a um elemento de interface em que ela costuma aparecer.', 0.4, 'O retângulo aparece em cartões, campos de digitação e áreas de toque de botões; o círculo aparece em fotos de perfil, selos numéricos de notificação e botões flutuantes; o triângulo aparece em setas de expansão de menus, ícones de reprodução de áudio e indicadores de rolagem.', 'Nota cheia: relaciona as três formas, cada uma a pelo menos um elemento correto da aula. Metade: relaciona corretamente só duas formas, ou relaciona as três mas com um elemento errado. Zero: não relaciona, relaciona errado ou fica em branco.'),
      (v_atividade, 1, 3, 'Explique por que essas formas organizam a tela melhor do que imagens complexas.', 0.4, 'O cérebro reconhece contornos geométricos conhecidos em milissegundos e gasta pouca energia para interpretar a tela; por isso as formas organizam a tela e reduzem o esforço mental, enquanto imagens complexas exigem mais interpretação.', 'Nota cheia: explica que as formas são reconhecidas rapidamente (ou com pouco esforço mental) e que isso organiza a tela, em comparação com imagens complexas. Metade: explica só um dos dois lados (rapidez ou organização). Zero: não explica, ou diz que imagens complexas são melhores, ou fica em branco.'),
      (v_atividade, 2, 1, 'Descreva a função do retângulo como contêiner universal.', 0.2, 'O retângulo funciona como contêiner universal, delimitando campos de digitação, cartões de conteúdo e a área de toque dos botões principais.', 'Nota cheia: descreve o retângulo como contêiner que delimita conteúdos (campos, cartões ou áreas de clique). Metade: diz que o retângulo "organiza" ou "separa" a tela, sem citar o que delimita. Zero: descreve outra forma, ou fica em branco.'),
      (v_atividade, 2, 2, 'Indique dois elementos da tela que devem ser delimitados por retângulos.', 0.4, 'Devem ser delimitados por retângulos, por exemplo, os campos de digitação (como o de nome ou de data) e os cartões de informação (como o da consulta ou o de dados do serviço). O botão também pode ser citado.', 'Nota cheia: indica dois elementos corretos (campo de digitação, cartão de informação ou botão). Metade: indica um elemento correto. Zero: indica elemento que não deve ser delimitado por retângulo, ou fica em branco.'),
      (v_atividade, 2, 3, 'Explique por que a área de toque dos botões principais também é tratada como retângulo.', 0.4, 'O retângulo maximiza a área de toque sem desperdiçar espaço vertical, e acomoda o texto do botão com preenchimento lateral confortável; como o polegar opera em eixos horizontal e vertical, a área retangular é mais fácil de acertar.', 'Nota cheia: explica que o retângulo amplia a área de toque e combina com o uso do polegar ou com o espaço do botão, com as palavras do aluno. Metade: cita só a ideia de área de toque, sem justificar. Zero: não justifica, justifica com algo fora da aula, ou fica em branco.'),
      (v_atividade, 3, 1, 'Diga para que serve o círculo na interface.', 0.2, 'O círculo representa identidade e destaque pontual, como fotos de perfil, selos numéricos de notificação e botões flutuantes.', 'Nota cheia: diz que o círculo representa identidade ou destaque e cita um exemplo da aula. Metade: diz a função sem exemplo, ou cita só um exemplo. Zero: atribui ao círculo a função de movimento ou direção, ou fica em branco.'),
      (v_atividade, 3, 2, 'Diga para que serve o triângulo na interface, com um exemplo de uso.', 0.4, 'O triângulo indica movimento e direção; por exemplo, a seta que expande um menu ou o ícone de reprodução de áudio.', 'Nota cheia: diz que o triângulo indica movimento ou direção e dá um exemplo correto (seta de expansão de menu, reprodução de áudio ou indicador de rolagem). Metade: diz a função sem exemplo correto. Zero: atribui ao triângulo a função de identidade, ou fica em branco.'),
      (v_atividade, 3, 3, 'Explique por que escolher a forma errada pode confundir o usuário.', 0.4, 'A forma serve de linguagem visual: se o usuário vê um círculo onde esperava uma seta, pode tentar tocar em um avatar como se fosse um menu, ou um triângulo onde esperava uma notificação, e se confunde sobre o que cada elemento faz.', 'Nota cheia: explica que a forma errada cria expectativa errada e leva o usuário a agir de forma incorreta ou a se confundir. Metade: afirma que confunde, sem explicar como. Zero: diz que a forma não faz diferença, ou fica em branco.'),
      (v_atividade, 4, 1, 'Explique por que os botões são quase sempre retângulos.', 0.2, 'Botões são quase sempre retângulos porque as telas e os polegares operam em eixos ortogonais (horizontal e vertical), e o retângulo acomoda palavras legíveis com preenchimento lateral confortável.', 'Nota cheia: cita o uso em eixos ortogonais (ou o polegar) e o acomodar do texto com preenchimento. Metade: cita só um dos dois motivos. Zero: dá motivo de estética, de moda ou de fora da aula, ou fica em branco.'),
      (v_atividade, 4, 2, 'Relacione a forma retangular com o uso do polegar e com o espaço da tela.', 0.4, 'O polegar alcança com facilidade uma área retangular, e a forma retangular maximiza a área de toque sem desperdiçar espaço vertical, o que é importante em uma tela com muitos textos longos.', 'Nota cheia: relaciona a forma retangular ao uso do polegar e ao aproveitamento do espaço vertical da tela. Metade: relaciona só ao polegar ou só ao espaço. Zero: não relaciona, ou relaciona com argumento contrário, ou fica em branco.'),
      (v_atividade, 4, 3, 'Diga qual forma você recomendaria para o botão de envio e justifique sua escolha.', 0.4, 'Recomenda-se o botão de envio retangular, pois ele maximiza a área de toque, combina com o espaço vertical de uma tela de cadastro com textos longos e mantém a legibilidade do texto do botão.', 'Nota cheia: indica a forma retangular e justifica com área de toque ou com o espaço da tela (uma das duas, com palavras do aluno, sem contradizer a aula). Metade: indica a forma retangular sem justificativa válida. Zero: indica a forma redonda sem justificar pela aula, ou fica em branco.'),
      (v_atividade, 5, 1, 'Descreva a sensação transmitida pelo canto reto (raio 0px).', 0.2, 'O canto reto (raio 0px) transmite seriedade, rigor técnico e uma arquitetura formal, por isso é comum em painéis corporativos e relatórios financeiros densos.', 'Nota cheia: descreve a sensação de seriedade ou rigor técnico. Metade: descreve a sensação de forma vaga (por exemplo, "formal"), sem o rigor. Zero: atribui ao canto reto a sensação de simpatia ou de modernidade amigável, ou fica em branco.'),
      (v_atividade, 5, 2, 'Descreva a sensação transmitida pelo canto em pílula (raio 24px).', 0.4, 'O canto em pílula (raio 24px) conduz a atenção para o centro do elemento e transmite simpatia, facilidade de uso e modernidade amigável, comum em redes sociais e jogos.', 'Nota cheia: descreve a sensação de simpatia, facilidade ou modernidade amigável. Metade: descreve a sensação de forma vaga (por exemplo, "bonito"), ou cita só o foco no centro. Zero: atribui a ela seriedade ou rigor, ou fica em branco.'),
      (v_atividade, 5, 3, 'Indique qual raio você escolheria para o painel financeiro e para o aplicativo social, justificando cada escolha.', 0.4, 'Para o painel financeiro, o raio deve ser 0px, por causa da seriedade e da densidade de dados; para o aplicativo social, o raio deve ser 24px (pílula), por causa da simpatia e da facilidade de uso.', 'Nota cheia: indica 0px para o painel financeiro e 24px para o aplicativo social, e justifica cada um com a sensação da aula. Metade: indica os dois raios corretos, mas justifica só um, ou justifica com argumento vago. Zero: troca os raios, ou fica em branco.'),
      (v_atividade, 6, 1, 'Diferencie o botão com preenchimento sólido do botão apenas com contorno (outline).', 0.2, 'O botão com preenchimento sólido transmite solidez e prioridade máxima; o botão apenas com contorno (outline) sinaliza ação secundária ou de cancelamento.', 'Nota cheia: diferencia o sólido (prioridade ou solidez) do contorno (ação secundária ou cancelamento). Metade: diferencia só por um dos lados. Zero: inverte as funções, ou fica em branco.'),
      (v_atividade, 6, 2, 'Explique qual dos dois botões deve receber preenchimento sólido e por quê.', 0.4, 'O botão "Confirmar consulta" deve receber preenchimento sólido, porque é a ação principal da tela, e o botão "Cancelar" deve ficar com contorno, porque é uma ação secundária.', 'Nota cheia: indica "Confirmar consulta" com sólido e "Cancelar" com contorno, e explica pela ação principal ou secundária. Metade: indica a escolha certa, sem explicar. Zero: escolhe o contrário, ou fica em branco.'),
      (v_atividade, 6, 3, 'Explique o que acontece quando dois botões sólidos concorrentes aparecem na mesma seção da tela.', 0.4, 'Dois botões sólidos concorrentes têm o mesmo peso visual, e o usuário não sabe qual é o fluxo principal; a regra de ouro proíbe dois botões sólidos com o mesmo peso na mesma seção de tela.', 'Nota cheia: explica que o usuário fica em dúvida sobre a ação principal, e cita a regra de ouro ou o mesmo peso visual. Metade: explica só a dúvida do usuário, sem a regra. Zero: diz que dois botões sólidos são melhores, ou fica em branco.'),
      (v_atividade, 7, 1, 'Nomeie os três níveis de hierarquia da tela.', 0.2, 'Os três níveis de hierarquia são o primário (ação principal), o secundário (apoio e contexto) e o terciário (detalhes opcionais).', 'Nota cheia: nomeia os três níveis: primário, secundário e terciário. Metade: nomeia dois dos três níveis. Zero: nomeia outros níveis, ou fica em branco.'),
      (v_atividade, 7, 2, 'Classifique os três grupos citados no contexto, um por nível.', 0.4, 'O botão de envio é nível primário; os filtros de horário são nível secundário; o aviso legal do rodapé é nível terciário.', 'Nota cheia: classifica os três grupos corretamente, um por nível. Metade: classifica dois corretamente. Zero: classifica um ou nenhum corretamente, ou fica em branco.'),
      (v_atividade, 7, 3, 'Explique como a hierarquia ajuda o usuário a completar a tarefa sem se distrair.', 0.4, 'A hierarquia mostra primeiro a ação principal, deixa o apoio disponível sem roubar a cena e relega os detalhes ao segundo plano, então o usuário completa a tarefa sem se distrair.', 'Nota cheia: explica que a ordem de importância guia o usuário à ação principal e evita distração pelos elementos de apoio ou detalhes. Metade: explica só a ideia de ordem, sem ligar à tarefa. Zero: não explica, ou fica em branco.'),
      (v_atividade, 8, 1, 'Explique qual posição na tela recebe foco prioritário antes da rolagem.', 0.2, 'Elementos situados no topo ou no centro da tela recebem foco prioritário antes da rolagem.', 'Nota cheia: cita o topo ou o centro como posição de foco prioritário, antes da rolagem. Metade: cita só um deles, ou diz "a parte de cima" sem mencionar a rolagem. Zero: cita o rodapé, ou fica em branco.'),
      (v_atividade, 8, 2, 'Explique como o espaço vazio ao redor de uma forma altera a atenção do usuário.', 0.4, 'Deixar áreas limpas ao redor de uma forma geométrica faz ela saltar aos olhos, porque o espaço vazio (respiro) diminui a competição com outros elementos e aumenta a atenção sobre a forma.', 'Nota cheia: explica que o espaço vazio isola a forma e aumenta a atenção. Metade: diz que o espaço "destaca" sem explicar o porquê. Zero: diz que espaço vazio desvia a atenção, ou fica em branco.'),
      (v_atividade, 8, 3, 'Proponha dois ajustes concretos para o botão do pé da página.', 0.4, 'Exemplos de ajustes: mover o botão para o topo ou para o centro da tela, e deixar um espaço livre ao redor dele, sem textos e ícones próximos; também vale usar preenchimento sólido com contraste.', 'Nota cheia: propõe dois ajustes concretos e corretos (posição no topo ou centro; espaço livre ao redor; contraste). Metade: propõe um ajuste concreto correto, ou dois ajustes vagos. Zero: propõe ajuste que piora a visibilidade, ou fica em branco.'),
      (v_atividade, 9, 1, 'Cite os três fatores que compõem o peso visual de um elemento.', 0.2, 'A aula apresenta a fórmula do peso visual com três fatores: tamanho (área geométrica total), contraste (diferença de valor contra o fundo) e espaço (respiro vazio ao redor da forma). O enunciado pede os três fatores da aula.', 'Nota cheia: cita tamanho, contraste e espaço, com a ideia de cada um. Metade: cita dois dos três fatores da aula. Zero: cita um fator ou nenhum, ou fica em branco.'),
      (v_atividade, 9, 2, 'Relacione cada cartão aos fatores do peso visual.', 0.4, 'O primeiro cartão é grande, mas tem tamanho alto e contraste fraco, com pouco espaço livre; o segundo é pequeno, mas tem alto contraste e espaço livre ao redor.', 'Nota cheia: relaciona cada cartão aos fatores corretos (tamanho, contraste e espaço do primeiro e do segundo). Metade: relaciona corretamente um dos dois cartões. Zero: relaciona os fatores de forma invertida, ou fica em branco.'),
      (v_atividade, 9, 3, 'Diga qual cartão atrai mais o olhar e explique por quê.', 0.4, 'O segundo cartão atrai mais o olhar, porque o alto contraste e o espaço livre compensam o tamanho menor, e o peso visual depende da soma dos fatores e não só do tamanho.', 'Nota cheia: indica o segundo cartão e explica pelo contraste e pelo espaço, reconhecendo que o tamanho menor é compensado. Metade: indica o segundo cartão, sem explicar pelos fatores. Zero: indica o primeiro cartão, ou fica em branco.'),
      (v_atividade, 10, 1, 'Informe o tamanho mínimo recomendado para a área de toque com o dedo.', 0.2, 'O tamanho mínimo recomendado para a área de toque com o dedo é de 44 por 44 pixels.', 'Nota cheia: informa 44x44px (ou 44 por 44 pixels). Metade: informa um valor próximo, mas errado, com a unidade certa. Zero: informa outro valor, sem unidade, ou fica em branco.'),
      (v_atividade, 10, 2, 'Compare o botão de 20 por 20 pixels com esse tamanho mínimo.', 0.4, 'O botão de 20 por 20 pixels tem menos da metade do tamanho mínimo em cada lado, ou seja, cerca de um quinto da área recomendada, e está abaixo do padrão ergonômico.', 'Nota cheia: compara o botão com 44x44px e diz que ele está abaixo do mínimo, com a diferença. Metade: diz que está abaixo do mínimo, sem a diferença. Zero: diz que o tamanho é adequado, ou fica em branco.'),
      (v_atividade, 10, 3, 'Explique por que esse problema afeta a usabilidade, mesmo que o botão esteja visível.', 0.4, 'Mesmo visível, o botão pequeno é difícil de acertar com o dedo, o que gera toques errados e frustração, e o usuário pode não conseguir completar a tarefa de confirmar a consulta.', 'Nota cheia: explica que a área pequena dificulta o toque (erros ou frustração) e prejudica a tarefa, apesar de estar visível. Metade: diz só que é difícil de tocar, sem ligar à tarefa. Zero: diz que a visibilidade resolve, ou fica em branco.'),
      (v_atividade, 11, 1, 'Defina contraste com suas palavras.', 0.2, 'Contraste é a diferença de valor (claro e escuro, ou de cor) entre um elemento e o fundo que o cerca, o que faz o elemento aparecer.', 'Nota cheia: define contraste como diferença entre o elemento e o fundo (de valor, claro/escuro ou cor). Metade: define de forma vaga, como "a cor que se destaca", sem a comparação com o fundo. Zero: define como "tamanho" ou "espaço", ou fica em branco.'),
      (v_atividade, 11, 2, 'Explique por que o botão cinza sobre fundo cinza prejudica a hierarquia visual.', 0.4, 'Cinza sobre cinza não tem diferença de valor, então o botão some; sem contraste, a hierarquia visual não aparece e o botão deixa de parecer a ação principal ou de convidar ao clique.', 'Nota cheia: explica que não há diferença entre botão e fundo e que isso quebra a hierarquia (o botão não se destaca). Metade: diz só que o botão some, sem ligar à hierarquia. Zero: diz que o problema é só de tamanho, ou fica em branco.'),
      (v_atividade, 11, 3, 'Descreva a transformação do botão com contraste sólido e cantos arredondados.', 0.4, 'O botão deve virar um retângulo com preenchimento sólido e forte, em uma cor com contraste com o fundo, e com cantos arredondados.', 'Nota cheia: descreve preenchimento sólido com contraste forte e cantos arredondados. Metade: descreve só um dos três elementos (preenchimento, contraste ou cantos). Zero: propõe manter o contorno cinza, ou fica em branco.'),
      (v_atividade, 12, 1, 'Cite a escala base e o uso típico dela.', 0.2, 'A escala base é a 1x, com textos de apoio e ícones de 16px a 24px.', 'Nota cheia: cita a escala 1x (base) e o uso em textos de apoio ou ícones (16px a 24px). Metade: cita a escala 1x com um uso incompleto. Zero: cita outra escala como base, ou fica em branco.'),
      (v_atividade, 12, 2, 'Relacione as escalas 2x e 4x com os elementos que cada uma destaca.', 0.4, 'A escala 2x é intermediária e destaca títulos de seção e botões principais; a escala 4x é de destaque (hero) e reserva banners de entrada e números de impacto.', 'Nota cheia: relaciona 2x a títulos de seção ou botões principais e 4x a banners ou números de impacto. Metade: relaciona corretamente só uma das duas escalas. Zero: troca as escalas, ou fica em branco.'),
      (v_atividade, 12, 3, 'Explique por que usar o mesmo tamanho para tudo prejudica a hierarquia da tela.', 0.4, 'Usar o mesmo tamanho para tudo elimina a ordem de importância: o usuário não distingue o título da seção do texto de apoio nem o banner do conteúdo, e a hierarquia da tela fica plana.', 'Nota cheia: explica que o mesmo tamanho apaga a diferença de importância entre os elementos (hierarquia). Metade: diz só que "fica confuso", sem ligar à hierarquia. Zero: defende a proposta da equipe, ou fica em branco.'),
      (v_atividade, 13, 1, 'Descreva o equilíbrio simétrico e a sensação que ele transmite.', 0.2, 'O equilíbrio simétrico espelha os elementos em relação ao centro, com o mesmo peso dos dois lados, e transmite ordem, tranquilidade e estabilidade.', 'Nota cheia: descreve o espelhamento em relação ao centro e a sensação de ordem ou estabilidade. Metade: descreve só o espelhamento, ou só a sensação. Zero: descreve outro tipo de equilíbrio, ou fica em branco.'),
      (v_atividade, 13, 2, 'Descreva o equilíbrio assimétrico e a sensação que ele transmite.', 0.4, 'O equilíbrio assimétrico compensa um objeto grande e denso de um lado com vários objetos menores e claros do outro, e transmite dinamismo, energia e modernidade.', 'Nota cheia: descreve a compensação entre um elemento grande e vários menores e a sensação de dinamismo ou modernidade. Metade: descreve só a compensação, ou só a sensação. Zero: descreve o espelhamento, ou fica em branco.'),
      (v_atividade, 13, 3, 'Indique qual composição usar na tela de login e justifique com o eixo central.', 0.4, 'Para a tela de login, deve-se usar o equilíbrio simétrico, pois a aula indica esse tipo para telas de login e páginas institucionais, e os elementos espelhados em relação ao eixo central facilitam a verificação do peso visual dos dois lados.', 'Nota cheia: escolhe o simétrico e justifica pelo eixo central (ou pela indicação de telas de login). Metade: escolhe o simétrico sem justificar pelo eixo. Zero: escolhe o assimétrico sem justificar, ou fica em branco.'),
      (v_atividade, 14, 1, 'Defina tensão visual com suas palavras.', 0.2, 'Tensão visual ocorre quando elementos desiguais não encontram contraponto na composição, gerando desconforto no leitor.', 'Nota cheia: define tensão visual como elementos desiguais sem contraponto que geram desconforto. Metade: define só como "desequilíbrio", sem o contraponto. Zero: define como harmonia, ou fica em branco.'),
      (v_atividade, 14, 2, 'Explique por que os elementos desiguais e sem alinhamento causam desconforto no leitor.', 0.4, 'Elementos desiguais sem alinhamento quebram a ordem da tela; o olhar não encontra um caminho previsível e fica inquieto, por isso causam desconforto.', 'Nota cheia: explica que a falta de alinhamento ou a desigualdade quebram a ordem e deixam o olhar sem caminho. Metade: cita só o desconforto, sem a causa. Zero: diz que a desigualdade é positiva, ou fica em branco.'),
      (v_atividade, 14, 3, 'Proponha uma correção para a tela, citando o alinhamento e o contraponto.', 0.4, 'Alinhar os elementos soltos a um mesmo eixo ou margem e colocar um contraponto do lado oposto ao bloco grande, como um elemento menor e claro, para equilibrar a composição.', 'Nota cheia: propõe a correção com alinhamento e contraponto (citados os dois). Metade: cita só um dos dois. Zero: propõe aumentar o bloco ou deixá-lo como está, ou fica em branco.'),
      (v_atividade, 15, 1, 'Explique o que é o método do raio-x visual.', 0.2, 'O método do raio-x visual é uma análise profissional em que se desenham retângulos transparentes sobre a tela para revelar a geometria oculta, em vez de opinar se a tela é bonita ou feia.', 'Nota cheia: descreve o método como análise geométrica com retângulos sobre os blocos, e diz que não é opinião estética. Metade: descreve só os retângulos, sem o caráter profissional. Zero: descreve como opinião estética, ou fica em branco.'),
      (v_atividade, 15, 2, 'Descreva como desenhar os retângulos transparentes sobre a tela.', 0.4, 'Desenhar retângulos transparentes em volta de cada bloco de conteúdo, como formulários e cartões, para mapear onde estão os blocos e as áreas com excesso de informação.', 'Nota cheia: indica desenhar um retângulo em volta de cada bloco de conteúdo. Metade: indica desenhar retângulos sem dizer em volta de quê. Zero: indica desenhar retângulos sobre o que não é bloco, ou fica em branco.'),
      (v_atividade, 15, 3, 'Explique o que você verifica com esses retângulos.', 0.4, 'Com os retângulos, verifica-se se o alinhamento dos blocos faz sentido e se as proporções estão corretas, ou seja, se os elementos estão alinhados entre si e com o tamanho adequado.', 'Nota cheia: cita a verificação do alinhamento e das proporções. Metade: cita só um dos dois. Zero: cita verificação estética (bonito ou feio), ou fica em branco.'),
      (v_atividade, 16, 1, 'Liste as quatro etapas da análise, sem ordená-las ainda.', 0.2, 'As quatro etapas da análise são: identificar os blocos retangulares de conteúdo; analisar a hierarquia dos botões e textos; verificar a proporção e o tamanho dos elementos interativos; propor ajustes de cantos, espaçamento e preenchimento.', 'Nota cheia: lista as quatro etapas com as palavras essenciais de cada uma. Metade: lista três etapas corretas. Zero: lista menos de três etapas corretas, ou fica em branco.'),
      (v_atividade, 16, 2, 'Coloque as etapas na ordem correta.', 0.4, 'A ordem correta é: 1) identificar os blocos retangulares; 2) analisar a hierarquia; 3) verificar a proporção e o tamanho; 4) propor os ajustes.', 'Nota cheia: coloca as quatro etapas nessa ordem. Metade: coloca corretamente três delas, ou troca duas posições que não sejam a primeira nem a última. Zero: coloca os ajustes antes da análise, ou fica em branco.'),
      (v_atividade, 16, 3, 'Justifique por que os ajustes de cantos e espaçamento vêm por último.', 0.4, 'Os ajustes de cantos e espaçamento vêm por último porque só fazem sentido depois de saber quais são os blocos, como está a hierarquia e se os elementos interativos têm o tamanho certo; ajustar antes disso seria corrigir no escuro.', 'Nota cheia: justifica que os ajustes dependem das etapas anteriores (conhecer blocos, hierarquia e proporção). Metade: diz só que "é a última etapa", sem justificar. Zero: justifica com a estética, ou fica em branco.'),
      (v_atividade, 17, 1, 'Formule a pergunta do checklist sobre a clareza dos contêineres.', 0.2, 'A pergunta do checklist é: "Cada assunto possui seu próprio cartão delimitado?"', 'Nota cheia: formula a pergunta sobre cada assunto ter cartão próprio e delimitado. Metade: formula a pergunta sobre clareza ou separação, sem o cartão delimitado. Zero: formula outra pergunta, ou fica em branco.'),
      (v_atividade, 17, 2, 'Explique o problema de manter os três assuntos no mesmo bloco.', 0.4, 'Três assuntos no mesmo bloco, sem divisão visual, confundem o usuário, porque ele não sabe onde termina um assunto e começa o outro, e o contêiner deixa de organizar o conteúdo.', 'Nota cheia: explica que sem divisão o usuário não distingue os assuntos e a estrutura se perde. Metade: diz só que "fica confuso", sem ligar à divisão. Zero: diz que está correto como está, ou fica em branco.'),
      (v_atividade, 17, 3, 'Proponha a divisão da seção em cartões.', 0.4, 'A seção deve ser dividida em três cartões, cada um com um assunto, delimitados por retângulos, com espaço entre eles.', 'Nota cheia: propõe três cartões (um por assunto) delimitados. Metade: propõe dividir, sem indicar um cartão por assunto. Zero: propõe juntar os assuntos ou fica em branco.'),
      (v_atividade, 18, 1, 'Formule a pergunta do checklist sobre o destaque único por seção.', 0.2, 'A pergunta do checklist é: "Existe apenas um botão sólido principal por seção de tela?"', 'Nota cheia: formula a pergunta sobre um único botão sólido principal por seção. Metade: formula a pergunta sobre botões, sem o "apenas um" ou "por seção". Zero: formula outra pergunta, ou fica em branco.'),
      (v_atividade, 18, 2, 'Registre se a seção cumpre o destaque único e explique a resposta.', 0.4, 'A seção não cumpre o destaque único, porque tem dois botões sólidos de mesmo peso, o que deixa o usuário sem saber qual é a ação principal.', 'Nota cheia: registra "não cumpre" e explica pelos dois botões sólidos de mesmo peso. Metade: registra "não cumpre" sem explicar. Zero: registra "cumpre", ou fica em branco.'),
      (v_atividade, 18, 3, 'Registre se o ícone cumpre a ergonomia geométrica e explique a resposta.', 0.4, 'O ícone não cumpre a ergonomia geométrica, porque é muito pequeno para o dedo e a área de toque fica abaixo do padrão de 44x44px.', 'Nota cheia: registra "não cumpre" e explica pela área de toque pequena e o padrão de 44x44px. Metade: registra "não cumpre" sem o padrão de tamanho. Zero: registra "cumpre", ou fica em branco.'),
      (v_atividade, 19, 1, 'Escolha a forma para o indicador de expansão de menu e explique a escolha.', 0.2, 'O indicador de expansão de menu deve ser um triângulo, porque o triângulo indica movimento e direção (a seta que aponta a expansão).', 'Nota cheia: escolhe o triângulo e justifica com movimento ou direção. Metade: escolhe o triângulo sem justificar. Zero: escolhe outra forma, ou fica em branco.'),
      (v_atividade, 19, 2, 'Escolha a forma para o indicador de notificações numéricas e explique a escolha.', 0.4, 'O indicador de notificações numéricas deve ser um círculo, porque o círculo é usado como selo numérico de notificação.', 'Nota cheia: escolhe o círculo e justifica como selo numérico de notificação. Metade: escolhe o círculo sem justificar. Zero: escolhe outra forma, ou fica em branco.'),
      (v_atividade, 19, 3, 'Explique por que a forma deve servir e facilitar a função prática do elemento.', 0.4, 'A forma deve servir e facilitar a função prática do elemento: a seta triangular mostra para onde o menu abre, e o círculo com número chama a atenção para as notificações sem atrapalhar a tela.', 'Nota cheia: explica que a forma deve facilitar a função, com um exemplo de cada elemento. Metade: explica a ideia geral, sem exemplos. Zero: diz que a forma não importa para a função, ou fica em branco.'),
      (v_atividade, 20, 1, 'Aponte o principal problema geométrico encontrado no mapeamento dos blocos de conteúdo.', 0.2, 'O principal problema geométrico do mapeamento é que os blocos de conteúdo estão misturados, com excesso de informação em um mesmo bloco, sem retângulos que os separem em cartões.', 'Nota cheia: aponta blocos misturados ou sem delimitação (contêineres) como problema geométrico. Metade: aponta excesso de informação, sem a relação com os contêineres. Zero: aponta só a cor ou o texto, ou fica em branco.'),
      (v_atividade, 20, 2, 'Aponte o problema de proporção e de contraste do botão de confirmar.', 0.4, 'O botão "Confirmar" tem área de toque de 20x20px, abaixo do mínimo de 44x44px, e está em cinza sobre fundo cinza, sem contraste, por isso não se destaca nem é fácil de tocar.', 'Nota cheia: aponta os dois problemas (proporção abaixo de 44x44px e contraste nulo ou insuficiente). Metade: aponta só um dos dois problemas. Zero: não aponta nenhum, ou fica em branco.'),
      (v_atividade, 20, 3, 'Proponha três melhorias, uma para cada passo do diagnóstico, justificando cada uma.', 0.4, 'Três melhorias, uma por passo: (1) mapear e separar os blocos em cartões delimitados por retângulos; (2) ampliar a área de toque do botão para pelo menos 44x44px; (3) aplicar contraste sólido ao botão, com preenchimento forte e cantos arredondados. Cada uma com justificativa pela regra da aula.', 'Nota cheia: propõe três melhorias, uma para cada passo (mapear blocos, checar proporção e aplicar contraste), cada uma com justificativa. Metade: propõe duas melhorias corretas, ou três sem justificativa. Zero: propõe melhorias fora da aula, ou fica em branco.');
end $$;
